/*
 Problem: 1331. Rank Transform of an Array
 Language: cpp
 Runtime: 35 ms (80.33%)
 Memory: 43.8 MB (60.52%)
 Tags: Array, Hash Table, Sorting
*/
class Solution {
public:
    vector<int> arrayRankTransform(vector<int>& arr) {
        vector<int> b = arr;
        sort(b.begin(), b.end());

        unordered_map<int, int> mp;
        int rank = 1;

        for (const auto& x : b) {
            if (!mp.count(x)) {
                mp[x] = rank;
                ++rank;
            }
        }

        for (auto &x : arr) x = mp[x];
        return arr;
    }
};
